style:
/* 绯樱 —— 顶部 RESUME 旗标、绯色实底标题条 */

.tw-feiying.layout-band.resume-paper .paper-flow::before {
  content: "RESUME";
  display: block;
  width: 46mm;
  margin: -3mm auto 7mm;
  padding: 1.6mm 0;
  background: var(--paper-accent);
  clip-path: polygon(4mm 0, 100% 0, calc(100% - 4mm) 100%, 0 100%);
  color: #fff;
  font-size: calc(var(--paper-base-size) * 1.16);
  font-weight: 700;
  letter-spacing: 0.34em;
  text-align: center;
  text-indent: 0.34em;
  print-color-adjust: exact;
}

.tw-feiying.layout-band.resume-paper .paper-header {
  margin-bottom: 6.5mm;
  padding-bottom: 4.4mm;
  border-bottom: 0.3mm solid #f6d9d7;
  align-items: flex-start;
  gap: 8mm;
}

.tw-feiying.layout-band.resume-paper .paper-header__main {
  flex: 1 1 auto;
  min-width: 0;
}

.tw-feiying.layout-band.resume-paper .paper-photo {
  order: 3;
  width: 25mm;
  height: 33mm;
  border: 0.5mm solid var(--paper-accent);
  border-radius: 0;
  box-shadow: none;
}

.tw-feiying.layout-band.resume-paper .paper-photo--monogram {
  display: grid;
  place-items: center;
  background: #fdf0ef;
  color: var(--paper-accent);
  font-size: calc(var(--paper-base-size) * 2);
  font-weight: 700;
}

.tw-feiying.layout-band.resume-paper .paper-name {
  color: var(--paper-accent);
  font-family: var(--paper-font-family);
  font-size: calc(var(--paper-base-size) * 2.1);
  letter-spacing: 0.06em;
}

.tw-feiying.layout-band.resume-paper .paper-identity {
  padding: 0;
  border: none;
  color: #a08382;
  font-size: calc(var(--paper-base-size) * 0.84);
}

.tw-feiying.layout-band.resume-paper .paper-role {
  margin-top: 1.4mm;
  color: #5c4c4b;
  font-size: calc(var(--paper-base-size) * 0.92);
  font-weight: 400;
}

.tw-feiying.layout-band.resume-paper .paper-contacts {
  display: flex;
  flex-wrap: wrap;
  gap: 1.4mm 6mm;
  margin-top: 3mm;
  padding-top: 0;
  border-top: none;
  color: #55494a;
  font-size: calc(var(--paper-base-size) * 0.86);
}

.tw-feiying.layout-band.resume-paper .paper-contact {
  display: inline-flex;
  gap: 1.4mm;
}

.tw-feiying.layout-band.resume-paper .paper-contact + .paper-contact::before {
  content: "|";
  left: -3mm;
  color: #f0cdcb;
}

.tw-feiying.layout-band.resume-paper .paper-contact__label {
  color: #a08a89;
}

/* 标题：绯色整条 + 白字 + 图标 */
.tw-feiying.layout-band.resume-paper .paper-style-block .paper-section__title {
  display: flex;
  align-items: center;
  gap: 2.4mm;
  margin-bottom: 3.2mm;
  padding: 1.2mm 3.2mm;
  background: var(--paper-accent);
  border-radius: 0;
  color: #fff;
  font-size: calc(var(--paper-base-size) * 1.04);
  letter-spacing: 0.12em;
  print-color-adjust: exact;
}

.tw-feiying.layout-band.resume-paper .paper-style-block .paper-section__icon {
  display: grid;
  flex: 0 0 auto;
  place-items: center;
  width: 4mm;
  height: 4mm;
  color: #fff;
}

.tw-feiying.layout-band.resume-paper .paper-style-block .paper-section__icon svg {
  width: 100%;
  height: 100%;
}

.tw-feiying.layout-band.resume-paper .paper-section__body {
  color: #3a3130;
}

.tw-feiying.layout-band.resume-paper .paper-item-title {
  color: #2a2221;
  font-size: calc(var(--paper-base-size) * 1.02);
}

.tw-feiying.layout-band.resume-paper .paper-item-period {
  color: #a08a89;
  font-size: calc(var(--paper-base-size) * 0.86);
}

.tw-feiying.layout-band.resume-paper .paper-item-sub {
  color: #4c4241;
}

.tw-feiying.layout-band.resume-paper .paper-rich ul,
.tw-feiying.layout-band.resume-paper .paper-rich ol {
  padding-left: 1.1em;
}

.tw-feiying.layout-band.resume-paper .paper-rich li::marker {
  color: var(--paper-accent);
}

.tw-feiying.layout-band.resume-paper .paper-skills {
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 2mm 7mm;
}

.tw-feiying.layout-band.resume-paper .paper-skill {
  display: block;
  padding-bottom: 0;
  border-bottom: none;
}

.tw-feiying.layout-band.resume-paper .paper-skill__name {
  display: block;
  font-size: calc(var(--paper-base-size) * 0.9);
  font-weight: 400;
}

.tw-feiying.layout-band.resume-paper .paper-skill__dots {
  display: flex;
  gap: 0;
  margin-top: 1.2mm;
}

.tw-feiying.layout-band.resume-paper .paper-skill__dots i {
  width: 100%;
  height: 1.8mm;
  border-radius: 0;
  background: #f7e5e4;
}

.tw-feiying.layout-band.resume-paper .paper-skill__dots i.filled {
  background: var(--paper-accent);
}

.tw-feiying.layout-band.resume-paper .paper-skill__level {
  display: block;
  margin-top: 1mm;
  color: #a08a89;
  font-size: calc(var(--paper-base-size) * 0.8);
}

.tw-feiying.layout-band.resume-paper .paper-note__tag {
  color: var(--paper-accent);
  font-weight: 600;
}

.tw-feiying.layout-band.resume-paper .paper-footer {
  border-top: 0.2mm solid #f7e6e5;
  color: #b3a09f;
}
